@router.get("/api/v1/tickets/{ticket_id}/assigned-team")
def get_ticket_team_directory(
    ticket_id: int,
    session: Session = Depends(get_session),
    current_user: User = Depends(get_current_user)
):
    ticket = session.exec(
        select(SupportTicket).where(
            SupportTicket.id == ticket_id,
            SupportTicket.creator_id == current_user.id
        )
    ).first()
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    support_agents = ticket.service_org.staff_members
    return [
        {"staff_id": staff.id, "email": staff.work_email, "phone_extension": staff.phone_ext, "role": staff.role}
        for staff in support_agents if staff.is_public_contact
    ]
